import { Controller, Get, Post, Put, Patch, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '급여 담당자';
// 마감 이후 상태에서는 수정·삭제·대상 변경을 막는다 (마감취소 후에만 가능)
const LOCKED = ['마감', '전표처리'];
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

function employeeIdsOf(value: unknown): number[] {
  if (!Array.isArray(value) || value.length === 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', '급여 대상 임직원을 지정하세요.');
  }
  const result: number[] = [];
  for (const item of value) {
    const n = Number(item);
    if (item === '' || item === null || !Number.isInteger(n) || n <= 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '임직원 ID는 양의 정수여야 합니다.');
    }
    result.push(n);
  }
  return result;
}

function textOf(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

@Controller('api/v1')
export class FnSfr02101Controller {
  @Get('/paydays')
  async listPaydays(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query) as Record<string, unknown>;
    const page = Math.max(0, Number(query['page'] ?? 0) || 0);
    const size = Math.min(200, Math.max(1, Number(query['size'] ?? 20) || 20));
    const payDateFrom = textOf(query['payDateFrom']);
    const payDateTo = textOf(query['payDateTo']);
    const status = textOf(query['status']);
    if ((payDateFrom && !DATE_RE.test(payDateFrom)) || (payDateTo && !DATE_RE.test(payDateTo))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 일자 형식이 올바르지 않습니다.');
    }
    const conditions: string[] = ['1 = 1'];
    const params: Record<string, unknown> = {};
    if (payDateFrom) {
      conditions.push('pay_date >= CAST(:payDateFrom AS date)');
      params['payDateFrom'] = payDateFrom;
    }
    if (payDateTo) {
      conditions.push('pay_date <= CAST(:payDateTo AS date)');
      params['payDateTo'] = payDateTo;
    }
    if (status) {
      conditions.push('status = :status');
      params['status'] = status;
    }
    const where = conditions.join(' AND ');
    return transaction(async (db) => {
      const totalRows = await db.query(`SELECT COUNT(*) AS "total" FROM payday WHERE ${where}`, params);
      const rows = await db.query(
        `SELECT payday_id AS "paydayId", pay_date AS "payDate", pay_type AS "payType", status AS "status"
         FROM payday WHERE ${where}
         ORDER BY pay_date DESC, payday_id DESC
         LIMIT :size OFFSET :offset`,
        { ...params, size, offset: page * size },
      );
      // 가정: 급여 대상자 테이블이 schema.sql에 없어 대상자 수는 0으로 둔다 (todos 참고)
      const items = rows.map((r: Record<string, unknown>) => ({ ...r, targetCount: 0 }));
      return { items, page, size, total: Number(totalRows[0]?.['total'] ?? 0) };
    });
  }

  @Post('/paydays')
  @HttpCode(200)
  async createPayday(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body) as Record<string, unknown>;
    const payDate = textOf(data['payDate']);
    const payType = textOf(data['payType']);
    if (!payDate || !DATE_RE.test(payDate)) {
      throw new ApiError(422, 'PAYDAY_INVALID', '급여 지급일을 입력하세요.');
    }
    if (!payType || payType.length > 50) {
      throw new ApiError(422, 'PAYDAY_INVALID', '급여 구분을 입력하세요 (50자 이내).');
    }
    if (!Array.isArray(data['employeeIds']) || data['employeeIds'].length === 0) {
      throw new ApiError(422, 'PAYDAY_INVALID', '급여 대상 임직원을 지정하세요.');
    }
    employeeIdsOf(data['employeeIds']);
    return transaction(async (db) => {
      const dup = await db.query(
        'SELECT payday_id FROM payday WHERE pay_date = CAST(:payDate AS date) AND pay_type = :payType',
        { payDate, payType },
      );
      if (dup.length > 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '같은 지급일·급여 구분이 이미 등록되어 있습니다.');
      }
      const rows = await db.query(
        `INSERT INTO payday (pay_date, pay_type, status, created_at, updated_at)
         VALUES (CAST(:payDate AS date), :payType, '등록', now(), now())
         RETURNING payday_id AS "paydayId"`,
        { payDate, payType },
      );
      return { paydayId: rows[0]['paydayId'] };
    });
  }

  @Put('/paydays/:paydayId/targets')
  @HttpCode(200)
  async replacePaydayTargets(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const paydayId = req.params['paydayId'];
    const data = checks.inputOf(req.body) as Record<string, unknown>;
    employeeIdsOf(data['employeeIds']);
    if (!/^\d+$/.test(paydayId)) {
      throw new ApiError(404, 'PAYDAY_NOT_FOUND', '급여 지급일을 찾을 수 없습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status AS "status" FROM payday WHERE payday_id = CAST(:paydayId AS bigint)',
        { paydayId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'PAYDAY_NOT_FOUND', '급여 지급일을 찾을 수 없습니다.');
      }
      if (LOCKED.includes(String(rows[0]['status']))) {
        throw new ApiError(409, 'PAYDAY_CLOSED', '마감된 지급일입니다. 마감취소 후 대상을 변경하세요.');
      }
      // 급여 대상 저장 테이블이 schema.sql에 없어 대상 목록은 저장하지 못한다 (todos 참고)
      await db.execute(
        'UPDATE payday SET updated_at = now() WHERE payday_id = CAST(:paydayId AS bigint)',
        { paydayId },
      );
      return { paydayId: Number(paydayId) };
    });
  }

  @Patch('/paydays/:paydayId')
  async updatePayday(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const paydayId = req.params['paydayId'];
    const data = checks.inputOf(req.body) as Record<string, unknown>;
    const newDate = textOf(data['payDate']);
    const newType = textOf(data['payType']);
    if (newDate && !DATE_RE.test(newDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '급여 지급일 형식이 올바르지 않습니다.');
    }
    if (newType.length > 50) {
      throw new ApiError(400, 'VALIDATION_FAILED', '급여 구분은 50자 이내로 입력하세요.');
    }
    if (!/^\d+$/.test(paydayId)) {
      throw new ApiError(404, 'PAYDAY_NOT_FOUND', '급여 지급일을 찾을 수 없습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT status AS "status", to_char(pay_date, 'YYYY-MM-DD') AS "payDate", pay_type AS "payType"
         FROM payday WHERE payday_id = CAST(:paydayId AS bigint)`,
        { paydayId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'PAYDAY_NOT_FOUND', '급여 지급일을 찾을 수 없습니다.');
      }
      if (LOCKED.includes(String(rows[0]['status']))) {
        throw new ApiError(409, 'PAYDAY_CLOSED', '마감된 지급일은 수정할 수 없습니다. 마감취소 후 수정하세요.');
      }
      const payDate = newDate || String(rows[0]['payDate']);
      const payType = newType || String(rows[0]['payType']);
      const dup = await db.query(
        `SELECT payday_id FROM payday
         WHERE pay_date = CAST(:payDate AS date) AND pay_type = :payType
           AND payday_id <> CAST(:paydayId AS bigint)`,
        { payDate, payType, paydayId },
      );
      if (dup.length > 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '같은 지급일·급여 구분이 이미 등록되어 있습니다.');
      }
      await db.execute(
        `UPDATE payday
         SET pay_date = CAST(:payDate AS date), pay_type = :payType, updated_at = now()
         WHERE payday_id = CAST(:paydayId AS bigint)`,
        { payDate, payType, paydayId },
      );
      return { paydayId: Number(paydayId) };
    });
  }

  @Delete('/paydays/:paydayId')
  async deletePayday(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const paydayId = req.params['paydayId'];
    if (!/^\d+$/.test(paydayId)) {
      throw new ApiError(404, 'PAYDAY_NOT_FOUND', '급여 지급일을 찾을 수 없습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status AS "status" FROM payday WHERE payday_id = CAST(:paydayId AS bigint)',
        { paydayId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'PAYDAY_NOT_FOUND', '급여 지급일을 찾을 수 없습니다.');
      }
      if (LOCKED.includes(String(rows[0]['status']))) {
        throw new ApiError(409, 'PAYDAY_CLOSED', '마감된 지급일은 삭제할 수 없습니다. 마감취소 후 삭제하세요.');
      }
      await db.execute('DELETE FROM payday WHERE payday_id = CAST(:paydayId AS bigint)', { paydayId });
      return {};
    });
  }
}

