import { useState } from 'react'
import {
  call, useData, Badge, DateText, Filters, Band, DataTable, Pager, Drawer, Tiles,
  Form, Field, TextInput, DateInput, Select,
} from '../kit'
import type { PageProps, Row, Page } from '../kit'

const STATUSES = ['등록', '계산완료', '과세집계완료', '마감', '전표처리', '마감취소']
const LOCKED = ['마감', '전표처리']
const SIZE = 20

type Mode = 'create' | 'edit' | 'targets' | 'delete'

function parseIds(text: string): number[] {
  const ids = text.split(',').map((s) => s.trim()).filter((s) => s !== '').map(Number)
  if (ids.length === 0) throw new Error('급여 대상 임직원 ID를 입력하세요.')
  if (ids.some((n) => !Number.isInteger(n) || n <= 0)) throw new Error('임직원 ID는 쉼표로 구분한 양의 정수여야 합니다.')
  return ids
}

export default function FnSfr02101Page({ role, notify }: PageProps) {
  const [page, setPage] = useState(0)
  const [from, setFrom] = useState('')
  const [to, setTo] = useState('')
  const [status, setStatus] = useState('')
  const [applied, setApplied] = useState({ from: '', to: '', status: '' })
  const [mode, setMode] = useState<Mode | null>(null)
  const [target, setTarget] = useState<Row | null>(null)
  const [payDate, setPayDate] = useState('')
  const [payType, setPayType] = useState('')
  const [idsText, setIdsText] = useState('')

  const list = useData<Page>(
    () => call<Page>('GET', '/paydays', role, undefined, {
      payDateFrom: applied.from,
      payDateTo: applied.to,
      status: applied.status,
      page,
      size: SIZE,
    }),
    [applied, page, role],
  )

  const rows = list.data?.items ?? []
  const total = list.data?.total ?? 0
  const waiting = rows.filter((r) => r.status === '등록' || r.status === '마감취소')

  function open(next: Mode, row: Row | null) {
    setMode(next)
    setTarget(row)
    setPayDate(row ? String(row.payDate ?? '') : '')
    setPayType(row ? String(row.payType ?? '') : '')
    setIdsText('')
  }

  function close() {
    setMode(null)
    setTarget(null)
  }

  function done(text: string) {
    notify(text)
    close()
    list.reload()
  }

  async function create() {
    if (!payDate) throw new Error('급여 지급일을 입력하세요.')
    if (!payType.trim()) throw new Error('급여 구분을 입력하세요.')
    const employeeIds = parseIds(idsText)
    await call('POST', '/paydays', role, { payDate, payType: payType.trim(), employeeIds })
    done('급여 지급일을 등록했습니다.')
  }

  async function update() {
    if (!target) return
    if (!payDate && !payType.trim()) throw new Error('수정할 값을 입력하세요.')
    await call('PATCH', `/paydays/${target.paydayId}`, role, { payDate, payType: payType.trim() })
    done('급여 지급일을 수정했습니다.')
  }

  async function replaceTargets() {
    if (!target) return
    const employeeIds = parseIds(idsText)
    await call('PUT', `/paydays/${target.paydayId}/targets`, role, { employeeIds })
    done('급여 대상을 변경했습니다.')
  }

  async function remove() {
    if (!target) return
    await call('DELETE', `/paydays/${target.paydayId}`, role)
    done('급여 지급일을 삭제했습니다.')
  }

  const columns = [
    { key: 'paydayId', label: '급여 지급일 ID' },
    { key: 'payDate', label: '급여 지급일', render: (r: Row) => <DateText value={r.payDate} /> },
    { key: 'payType', label: '급여 구분' },
    { key: 'status', label: '처리 상태', render: (r: Row) => <Badge value={r.status} /> },
    { key: 'targetCount', label: '급여 대상자 수' },
    {
      key: 'actions',
      label: '처리',
      render: (r: Row) => {
        if (LOCKED.includes(String(r.status))) return <span>마감됨</span>
        return (
          <span>
            <button type="button" onClick={(e) => { e.stopPropagation(); open('edit', r) }}>수정</button>
            <button type="button" onClick={(e) => { e.stopPropagation(); open('targets', r) }}>대상 변경</button>
            <button type="button" onClick={(e) => { e.stopPropagation(); open('delete', r) }}>삭제</button>
          </span>
        )
      },
    },
  ]

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>지급일 현황</h2>
        <Tiles items={[['전체 지급일', total], ['처리 대기(현재 쪽)', waiting.length]]} />
      </section>

      <section className="box span-8">
        <h2>급여 지급일</h2>
        <Filters
          onSearch={() => { setPage(0); setApplied({ from, to, status }) }}
          onReset={() => {
            setFrom('')
            setTo('')
            setStatus('')
            setPage(0)
            setApplied({ from: '', to: '', status: '' })
          }}
        >
          <Field label="지급일 조회 시작일"><DateInput value={from} onChange={setFrom} /></Field>
          <Field label="지급일 조회 종료일"><DateInput value={to} onChange={setTo} /></Field>
          <Field label="처리 상태">
            <Select value={status} onChange={setStatus} options={STATUSES.map((s): [string, string] => [s, s])} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={total}>
          <button type="button" onClick={() => open('create', null)}>지급일 등록</button>
        </Band>
        <DataTable columns={columns} rows={rows} empty="등록된 급여 지급일이 없습니다." />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>

      <section className="box span-4">
        <h2>처리 대기</h2>
        <DataTable
          columns={[
            { key: 'payDate', label: '급여 지급일', render: (r: Row) => <DateText value={r.payDate} /> },
            { key: 'payType', label: '급여 구분' },
            { key: 'status', label: '처리 상태', render: (r: Row) => <Badge value={r.status} /> },
          ]}
          rows={waiting}
          empty="처리 대기 지급일이 없습니다."
        />
      </section>

      {mode === 'create' && (
        <Drawer title="급여 지급일 등록" onClose={close}>
          <Form onSubmit={create} submit="등록">
            <Field label="급여 지급일" required><DateInput value={payDate} onChange={setPayDate} /></Field>
            <Field label="급여 구분" required><TextInput value={payType} onChange={setPayType} /></Field>
            <Field label="급여 대상 임직원 ID 목록" required wide hint="쉼표로 구분 (예: 1, 2, 3)">
              <TextInput value={idsText} onChange={setIdsText} />
            </Field>
          </Form>
        </Drawer>
      )}

      {mode === 'edit' && target && (
        <Drawer title="급여 지급일 수정" onClose={close}>
          <Form onSubmit={update} submit="수정">
            <Field label="급여 지급일"><DateInput value={payDate} onChange={setPayDate} /></Field>
            <Field label="급여 구분"><TextInput value={payType} onChange={setPayType} /></Field>
          </Form>
        </Drawer>
      )}

      {mode === 'targets' && target && (
        <Drawer title="급여 대상 변경" onClose={close}>
          <Form onSubmit={replaceTargets} submit="대상 변경">
            <Field label="급여 대상 임직원 ID 목록" required wide hint="쉼표로 구분 (예: 1, 2, 3)">
              <TextInput value={idsText} onChange={setIdsText} />
            </Field>
          </Form>
        </Drawer>
      )}

      {mode === 'delete' && target && (
        <Drawer title="급여 지급일 삭제" onClose={close}>
          <Form onSubmit={remove} submit="삭제" danger note="삭제한 급여 지급일은 되돌릴 수 없습니다." />
        </Drawer>
      )}
    </div>
  )
}
